.res-chip{display:flex;align-items:center;gap:5px;height:29px;padding:0 9px 0 7px;border-radius:999px;
  background:rgba(13,36,32,.54);border:1px solid rgba(245,238,219,.12);
  box-shadow:0 3px 12px rgba(0,0,0,.12);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  color:var(--cream);font-size:11.5px;font-weight:700;font-variant-numeric:tabular-nums}
.res-chip svg{width:14px;height:14px;color:var(--c);fill:currentColor;fill-opacity:.14;stroke:currentColor;stroke-width:1.6;stroke-linejoin:round}
.res-chip .count{min-width:8px;text-align:center}
button.res-chip{pointer-events:auto;transition:transform .15s ease,background .2s}
button.res-chip:active{transform:scale(.93)}
.food-chip.urgent{border-color:rgba(231,193,132,.55);box-shadow:0 0 0 1px rgba(231,193,132,.18),0 0 18px rgba(231,193,132,.18);animation:foodUrge 2.2s ease-in-out infinite}
#game.night .res-chip{background:rgba(7,20,34,.62);border-color:rgba(200,215,240,.13)}
.tool-badge{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;
  background:rgba(231,193,132,.12);border:1px solid rgba(231,193,132,.3);color:var(--gold);
  animation:badgeIn .4s cubic-bezier(.2,.9,.3,1.3)}
.tool-badge svg{width:14px;height:14px;fill:currentColor;fill-opacity:.1;stroke:currentColor;stroke-width:1.6;stroke-linejoin:round}

.hud-right{position:absolute;top:calc(9px + var(--safe-t));right:calc(11px + var(--safe-r));display:flex;flex-direction:column;align-items:center;gap:8px}
.daydial{display:flex;flex-direction:column;align-items:center;gap:3px;pointer-events:none}
.dial-face{position:relative;width:56px;height:56px;border-radius:50%;padding:4px;
  background:conic-gradient(from 0deg,#e7c184 0deg,#f0d59f 78deg,#d99a6c 168deg,#8a7d92 196deg,#33446d 224deg,#1c2a4c 250deg,#1c2a4c 344deg,#6f809e 360deg);
  box-shadow:0 5px 18px rgba(0,0,0,.22),inset 0 0 0 1px rgba(255,255,255,.18)}
.dial-face::before{content:"";position:absolute;inset:4px;border-radius:50%;background:radial-gradient(circle at 40% 32%,rgba(37,63,55,.85),rgba(8,25,25,.9));backdrop-filter:blur(6px)}
.dial-icon{position:absolute;left:50%;top:50%;width:17px;height:17px;transform:translate(-50%,-50%);
  color:#f0d59f;fill:currentColor;fill-opacity:.15;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;z-index:1;transition:color .6s}
.dial-face.night .dial-icon{color:#b9c9e8}
.dial-marker{position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px;border-radius:50%;
  background:#fff7e6;box-shadow:0 0 7px rgba(255,244,214,.9);z-index:2;
  transform:rotate(var(--a,0deg)) translateY(-24px);transition:transform .2s linear}
.dial-label{font-size:8.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:rgba(245,238,219,.64);white-space:nowrap}

.icon-btn{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;pointer-events:auto;
  background:rgba(13,36,32,.5);border:1px solid rgba(245,238,219,.13);
  box-shadow:0 4px 14px rgba(0,0,0,.16);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  color:rgba(245,238,219,.8);transition:background .2s,transform .15s}
.icon-btn:active{transform:scale(.92)}
.icon-btn svg{width:17px;height:17px;fill:currentColor;fill-opacity:.12;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.sound-btn{width:34px;height:34px}
.sound-btn svg{width:15px;height:15px}
#game.night .icon-btn{background:rgba(7,20,34,.6);border-color:rgba(200,215,240,.13)}

.joystick-zone{position:absolute;left:calc(4px + var(--safe-l));bottom:calc(6px + var(--safe-b));width:172px;height:172px;
  z-index:12;touch-action:none;pointer-events:auto;display:flex;align-items:flex-end;justify-content:flex-start}
.stick-base{position:relative;width:116px;height:116px;margin:0 0 18px 18px;border-radius:50%;
  background:radial-gradient(circle at 38% 32%,rgba(245,238,219,.13),rgba(10,30,27,.32) 72%);
  border:1px solid rgba(245,238,219,.15);
  box-shadow:inset 0 0 26px rgba(0,0,0,.18),0 8px 28px rgba(0,0,0,.16);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);transition:background .2s}
.joystick-zone.active .stick-base{background:radial-gradient(circle at 38% 32%,rgba(245,238,219,.19),rgba(10,30,27,.36) 72%)}
.stick-guide{position:absolute;inset:23px;border-radius:50%;border:1px dashed rgba(245,238,219,.13)}
.stick-knob{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px;border-radius:50%;
  background:radial-gradient(circle at 36% 28%,#f8f1df,#ddd4bd 58%,#bcb6a2);
  border:1px solid rgba(255,255,255,.5);
  box-shadow:0 6px 16px rgba(0,0,0,.28),inset 0 -3px 7px rgba(0,0,0,.1);
  will-change:transform}
.joystick-zone.active .stick-knob{box-shadow:0 8px 20px rgba(0,0,0,.34),inset 0 -3px 7px rgba(0,0,0,.1)}
#game.night .stick-base{background:radial-gradient(circle at 38% 32%,rgba(200,215,240,.12),rgba(6,18,32,.4) 72%);border-color:rgba(200,215,240,.14)}

.action-wrap{position:absolute;right:calc(17px + var(--safe-r));bottom:calc(23px + var(--safe-b));z-index:13;pointer-events:none}
.action-btn{position:relative;width:92px;height:92px;border-radius:50%;
  background:radial-gradient(circle at 36% 28%,rgba(245,238,219,.22),rgba(16,42,36,.74) 74%);
  border:1px solid rgba(245,238,219,.22);color:var(--cream);
  box-shadow:0 10px 30px rgba(0,0,0,.28),inset 0 0 0 1px rgba(255,255,255,.05),inset 0 0 30px rgba(0,0,0,.12);
  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
  opacity:0;transform:scale(.72);pointer-events:none;
  transition:opacity .18s ease,transform .18s cubic-bezier(.2,.9,.3,1.2)}
.action-wrap.visible .action-btn{opacity:1;transform:scale(1);pointer-events:auto}
.action-btn:active{transform:scale(.96)}
.action-progress{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg);pointer-events:none}
.action-track{fill:none;stroke:rgba(245,238,219,.14);stroke-width:3}
.action-fill{fill:none;stroke:var(--gold);stroke-width:3.5;stroke-linecap:round;stroke-dasharray:283;stroke-dashoffset:283;
  filter:drop-shadow(0 0 4px rgba(231,193,132,.5));transition:stroke-dashoffset .08s linear}
.action-inner{position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;pointer-events:none}
.action-icon{width:26px;height:26px;color:#f3ead5;fill:currentColor;fill-opacity:.13;stroke:currentColor;stroke-width:1.5;stroke-linejoin:round}
.action-label{font-size:10.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:#f3ead5}
#game.night .action-btn{background:radial-gradient(circle at 36% 28%,rgba(200,215,240,.18),rgba(7,20,34,.78) 74%);border-color:rgba(200,215,240,.18)}

.craft-btn{position:absolute;right:calc(36px + var(--safe-r));bottom:calc(132px + var(--safe-b));z-index:13;
  width:54px;height:54px;border-radius:50%;display:grid;place-items:center;pointer-events:auto;
  background:radial-gradient(circle at 36% 28%,rgba(245,238,219,.2),rgba(14,38,33,.7) 74%);
  border:1px solid rgba(245,238,219,.2);color:#f0e6ce;
  box-shadow:0 7px 22px rgba(0,0,0,.22),inset 0 0 18px rgba(0,0,0,.12);
  backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px);transition:transform .15s,background .2s}
.craft-btn:active{transform:scale(.92)}
.craft-btn svg{width:22px;height:22px;fill:currentColor;fill-opacity:.12;stroke:currentColor;stroke-width:1.5;stroke-linejoin:round}
.craft-dot{position:absolute;top:1px;right:1px;width:10px;height:10px;border-radius:50%;background:var(--gold);
  box-shadow:0 0 9px rgba(231,193,132,.9);opacity:0;transform:scale(.6);transition:opacity .3s,transform .3s}
.craft-dot.show{opacity:1;transform:scale(1)}
#game.night .craft-btn{background:radial-gradient(circle at 36% 28%,rgba(200,215,240,.16),rgba(7,20,34,.76) 74%);border-color:rgba(200,215,240,.16)}

.toasts{position:absolute;left:50%;bottom:calc(186px + var(--safe-b));transform:translateX(-50%);z-index:20;
  display:flex;flex-direction:column;align-items:center;gap:7px;width:max-content;max-width:min(86vw,430px);pointer-events:none}
.toast{padding:9px 16px;border-radius:999px;background:rgba(11,31,28,.8);border:1px solid rgba(245,238,219,.15);
  color:rgba(245,238,219,.92);font-size:12.5px;line-height:1.35;text-align:center;
  box-shadow:0 8px 26px rgba(0,0,0,.25);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  animation:toastIn .4s cubic-bezier(.2,.9,.3,1.1)}
.toast.out{animation:toastOut .45s ease forwards}
.toast b{color:var(--gold-soft);font-weight:800}

.sheet{position:absolute;left:0;right:0;bottom:0;z-index:30;max-height:74dvh;
  background:linear-gradient(180deg,rgba(22,48,43,.93),rgba(9,26,24,.98));
  border-radius:27px 27px 0 0;border-top:1px solid rgba(245,238,219,.17);
  box-shadow:0 -24px 70px rgba(0,0,0,.42);
  backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px);
  transform:translateY(105%);transition:transform .4s cubic-bezier(.2,.8,.2,1);
  padding-bottom:var(--safe-b);touch-action:pan-y}
.sheet.open{transform:translateY(0)}
.sheet-scroll{max-height:74dvh;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;
  padding:8px 18px 22px;scrollbar-width:none}
.sheet-scroll::-webkit-scrollbar{display:none}
.sheet-handle{width:40px;height:4px;border-radius:99px;background:rgba(245,238,219,.22);margin:0 auto 12px}
.sheet-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.eyebrow{margin:0;font-size:9px;font-weight:800;letter-spacing:.22em;text-transform:uppercase;color:rgba(245,238,219,.5)}
.sheet-head h2{margin:3px 0 0;font-family:Georgia,"Iowan Old Style","Times New Roman",serif;font-weight:400;
  font-size:30px;line-height:1;letter-spacing:-.01em;color:#f6efdc}
.close-btn{width:34px;height:34px;flex:none;margin-top:2px}
.sheet-res{display:flex;gap:7px;margin-bottom:15px;flex-wrap:wrap}
.sheet-res .res-chip{height:30px;background:rgba(245,238,219,.06);border-color:rgba(245,238,219,.12)}
.recipes{display:flex;flex-direction:column;gap:9px}
.recipe{display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:11px;
  padding:11px 12px;border-radius:17px;background:rgba(245,238,219,.045);
  border:1px solid rgba(245,238,219,.08);transition:background .2s,border-color .2s}
.recipe.affordable{background:rgba(245,238,219,.07);border-color:rgba(231,193,132,.16)}
.recipe-icon{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;flex:none;
  background:radial-gradient(circle at 36% 28%,rgba(231,193,132,.2),rgba(231,193,132,.05) 75%);
  border:1px solid rgba(231,193,132,.18);color:var(--gold)}
.recipe-icon svg{width:22px;height:22px;fill:currentColor;fill-opacity:.12;stroke:currentColor;stroke-width:1.5;stroke-linejoin:round}
.recipe-body{min-width:0}
.recipe h3{margin:0;font-size:13.5px;font-weight:800;letter-spacing:.01em;color:#f5eedb;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.recipe-tag{font-size:8px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:rgba(245,238,219,.5);
  border:1px solid rgba(245,238,219,.16);border-radius:99px;padding:2px 6px}
.recipe p{margin:2px 0 0;font-size:10.5px;line-height:1.35;color:rgba(245,238,219,.55)}
.cost{display:flex;gap:8px;margin-top:5px;flex-wrap:wrap}
.cost span{display:flex;align-items:center;gap:3px;font-size:10px;font-weight:700;color:rgba(245,238,219,.72);font-variant-numeric:tabular-nums}
.cost span.short{color:#e3a08c}
.cost svg{width:12px;height:12px;fill:currentColor;fill-opacity:.12;stroke:currentColor;stroke-width:1.7}
.craft-action{height:35px;min-width:66px;padding:0 12px;border-radius:999px;flex:none;
  background:linear-gradient(180deg,#f3e7ca,#ddcaa2);color:#1d3a30;font-size:10.5px;font-weight:900;
  letter-spacing:.08em;text-transform:uppercase;box-shadow:0 4px 12px rgba(0,0,0,.18),inset 0 1px 0 rgba(255,255,255,.5);
  transition:transform .15s,opacity .2s,background .2s}
.craft-action:active{transform:scale(.94)}
.craft-action:disabled{background:rgba(245,238,219,.1);color:rgba(245,238,219,.38);box-shadow:none;cursor:default}
.craft-action.owned{background:rgba(159,182,143,.16);color:#b9caa9;border:1px solid rgba(159,182,143,.28)}
.sheet-note{display:flex;align-items:center;gap:7px;margin:14px 2px 0;font-size:10px;line-height:1.4;color:rgba(245,238,219,.42)}
.sheet-note svg{width:13px;height:13px;flex:none;fill:currentColor;fill-opacity:.15;stroke:currentColor;stroke-width:1.6}

.overlay{position:absolute;inset:0;z-index:40;display:flex;align-items:center;justify-content:center;padding:22px}
.title{background:linear-gradient(180deg,rgba(9,28,31,.42),rgba(6,21,25,.72));transition:opacity .9s ease,visibility .9s}
.title.hidden{opacity:0;visibility:hidden;pointer-events:none}
.title-bg{position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(ellipse at 50% 38%,rgba(240,213,159,.13),transparent 55%),
             radial-gradient(ellipse at 50% 110%,rgba(4,12,18,.55),transparent 68%)}
.title-card{position:relative;text-align:center;max-width:420px;width:100%;padding:30px 26px 24px;border-radius:29px;
  background:linear-gradient(180deg,rgba(22,50,44,.55),rgba(9,27,25,.74));
  border:1px solid rgba(245,238,219,.16);
  box-shadow:0 34px 90px rgba(0,0,0,.42),inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);animation:cardIn .9s cubic-bezier(.2,.8,.2,1)}
.title-card h1{margin:9px 0 13px;font-family:Georgia,"Iowan Old Style","Times New Roman",serif;
  font-weight:400;font-size:clamp(42px,12.5vw,62px);line-height:.98;letter-spacing:-.025em;color:#f7f0dd;
  text-shadow:0 4px 30px rgba(0,0,0,.25)}
.title-card h1 em{font-style:italic;color:#dcc798}
.tagline{margin:0 auto 21px;max-width:300px;font-size:12.5px;line-height:1.7;color:rgba(245,238,219,.68)}
.primary{min-width:186px;height:52px;padding:0 26px;border-radius:999px;
  background:linear-gradient(180deg,#f6ecd4,#ddcaa5);color:#1b3a30;
  font-size:12px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;
  box-shadow:0 12px 30px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.65);
  transition:transform .16s,opacity .25s,filter .2s}
.primary:active{transform:scale(.97)}
.primary:disabled{opacity:.45;filter:saturate(.4)}
.controls-hint{display:flex;align-items:center;justify-content:center;gap:9px;margin-top:20px;
  font-size:9.5px;font-weight:700;letter-spacing:.06em;color:rgba(245,238,219,.5);flex-wrap:wrap}
.hint-item{display:flex;align-items:center;gap:4px;white-space:nowrap}
.hint-item svg{width:13px;height:13px;fill:currentColor;fill-opacity:.12;stroke:currentColor;stroke-width:1.6}
.hint-stick{width:12px;height:12px;border-radius:50%;border:1px solid rgba(245,238,219,.42);position:relative}
.hint-stick::after{content:"";position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px;border-radius:50%;background:rgba(245,238,219,.7)}
.hint-ring{width:12px;height:12px;border-radius:50%;border:1.5px solid rgba(231,193,132,.7);position:relative}
.hint-ring::after{content:"";position:absolute;inset:3px;border-radius:50%;background:rgba(231,193,132,.45)}
.hint-sep{width:1px;height:10px;background:rgba(245,238,219,.16)}
.loading{margin:13px 0 0;font-size:8.5px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:rgba(245,238,219,.36);min-height:11px;transition:opacity .5s}

.faint{z-index:50;background:rgba(5,13,22,.74);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.faint-card{text-align:center;max-width:350px;padding:30px 26px;border-radius:26px;
  background:linear-gradient(180deg,rgba(20,38,50,.75),rgba(7,20,30,.9));
  border:1px solid rgba(200,215,240,.16);box-shadow:0 30px 80px rgba(0,0,0,.45)}
.faint-card h2{margin:7px 0 8px;font-family:Georgia,"Iowan Old Style",serif;font-weight:400;font-size:32px;color:#eef0e6}
.faint-card p:not(.eyebrow){margin:0 0 20px;font-size:12.5px;line-height:1.6;color:rgba(235,238,228,.64)}
.faint[hidden]{display:none}

@keyframes softPulse{0%,100%{opacity:1}50%{opacity:.45}}
@keyframes foodUrge{0%,100%{box-shadow:0 0 0 1px rgba(231,193,132,.18),0 0 16px rgba(231,193,132,.14)}50%{box-shadow:0 0 0 1px rgba(231,193,132,.4),0 0 22px rgba(231,193,132,.3)}}
@keyframes badgeIn{from{opacity:0;transform:scale(.4)}to{opacity:1;transform:scale(1)}}
@keyframes toastIn{from{opacity:0;transform:translateY(10px) scale(.96)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes toastOut{to{opacity:0;transform:translateY(-6px) scale(.97)}}
@keyframes cardIn{from{opacity:0;transform:translateY(16px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}

@media (max-height:540px){
  .title-card{padding:20px 24px 16px;max-width:390px}
  .title-card h1{font-size:clamp(34px,7vw,46px);margin:6px 0 9px}
  .tagline{font-size:11px;margin-bottom:14px;line-height:1.55}
  .controls-hint{margin-top:12px}
  .loading{margin-top:8px}
  .primary{height:46px;min-width:168px}
  .sheet{left:auto;right:calc(12px + var(--safe-r));top:calc(12px + var(--safe-t));bottom:calc(12px + var(--safe-b));width:min(390px,47vw);max-height:none;
    border-radius:22px;border:1px solid rgba(245,238,219,.16);transform:translateX(112%)}
  .sheet.open{transform:translateX(0)}
  .sheet-scroll{max-height:calc(100dvh - 24px - var(--safe-t) - var(--safe-b))}
  .sheet-handle{display:none}
  .sheet-scroll{padding:16px 16px 18px}
  .toasts{bottom:auto;top:calc(84px + var(--safe-t));max-width:min(58vw,380px)}
  .action-btn{width:80px;height:80px}
  .action-icon{width:23px;height:23px}
  .craft-btn{width:48px;height:48px;bottom:calc(114px + var(--safe-b));right:calc(33px + var(--safe-r))}
  .craft-btn svg{width:19px;height:19px}
  .joystick-zone{width:150px;height:150px}
  .stick-base{width:102px;height:102px;margin-bottom:16px;margin-left:16px}
  .stick-guide{inset:20px}
  .stick-knob{width:46px;height:46px;margin:-23px}
  .meter{width:52px;height:52px}
  .meter .fill{stroke-dasharray:141}
  .res-chip{height:27px;font-size:11px}
  .hud-left{gap:6px}
  .dial-face{width:50px;height:50px}
  .dial-marker{transform:rotate(var(--a,0deg)) translateY(-21px)}
}
@media (max-width:360px){
  .meter{width:52px;height:52px}
  .meter .fill{stroke-dasharray:141}
  .res-chip{height:27px;padding:0 8px 0 6px;font-size:10.5px}
  .inventory{gap:5px}
  .action-btn{width:84px;height:84px}
  .craft-btn{width:48px;height:48px;bottom:calc(122px + var(--safe-b));right:calc(35px + var(--safe-r))}
  .joystick-zone{width:154px;height:154px}
  .stick-base{width:104px;height:104px;margin-left:12px}
  .title-card{padding:26px 20px 20px}
  .controls-hint{gap:7px;font-size:9px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}

export const TAU = Math.PI * 2;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => clamp((v - a) / (b - a), 0, 1);
export const smoothstep = (a, b, v) => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const mix = (a, b, t) => [
  lerp(a[0], b[0], t),
  lerp(a[1], b[1], t),
  lerp(a[2], b[2], t),
];

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function rand() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hash2(x, y, seed = 0) {
  let h = Math.imul(x | 0, 374761393) + Math.imul(y | 0, 668265263) + Math.imul(seed | 0, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

export class Noise {
  constructor(seed = 1) {
    this.seed = seed | 0;
  }
  hash(x, y) {
    return hash2(x, y, this.seed);
  }
  noise(x, y) {
    const x0 = Math.floor(x);
    const y0 = Math.floor(y);
    const fx = x - x0;
    const fy = y - y0;
    const u = fx * fx * (3 - 2 * fx);
    const v = fy * fy * (3 - 2 * fy);
    const a = this.hash(x0, y0);
    const b = this.hash(x0 + 1, y0);
    const c = this.hash(x0, y0 + 1);
    const d = this.hash(x0 + 1, y0 + 1);
    return lerp(lerp(a, b, u), lerp(c, d, u), v);
  }
  fbm(x, y, octaves = 4, lacunarity = 2, gain = 0.5) {
    let amp = 1;
    let freq = 1;
    let sum = 0;
    let norm = 0;
    for (let i = 0; i < octaves; i++) {
      sum += amp * this.noise(x * freq + i * 17.13, y * freq - i * 9.71);
      norm += amp;
      amp *= gain;
      freq *= lacunarity;
    }
    return sum / norm;
  }
}

export const rgb = (r, g, b) => `rgb(${r | 0},${g | 0},${b | 0})`;
export const rgba = (r, g, b, a) => `rgba(${r | 0},${g | 0},${b | 0},${a})`;

export function shade(color, amount) {
  return [
    clamp(color[0] + amount, 0, 255),
    clamp(color[1] + amount, 0, 255),
    clamp(color[2] + amount, 0, 255),
  ];
}

