import { TAU, clamp, lerp, smoothstep, mulberry32, hash2, Noise } from './util.js';

export const WORLD = 2400;
const GRID = 600;
const HALF = WORLD / 2;

export const RESOURCE_META = {
  tree: {
    name: 'Pine Tree',
    action: 'Chop',
    icon: 'axe',
    resource: 'wood',
    resourceName: 'Wood',
    duration: 1.15,
    respawn: 52,
    hits: 3,
    reach: 84,
    radius: 15,
  },
  rock: {
    name: 'Boulder',
    action: 'Mine',
    icon: 'pick',
    resource: 'stone',
    resourceName: 'Stone',
    duration: 1.38,
    respawn: 66,
    hits: 3,
    reach: 80,
    radius: 18,
  },
  bush: {
    name: 'Berry Bush',
    action: 'Pick',
    icon: 'berry',
    resource: 'food',
    resourceName: 'Berries',
    duration: 0.88,
    respawn: 42,
    hits: 2,
    reach: 74,
    radius: 14,
  },
};

const WATER_DEEP = [20, 68, 84];
const WATER_MID = [38, 108, 120];
const WATER_SHALLOW = [92, 168, 158];
const FOAM = [203, 224, 207];
const WET_SAND = [181, 164, 124];
const SAND = [211, 190, 146];
const SAND_LIGHT = [224, 205, 162];
const GRASS_EDGE = [126, 148, 90];
const GRASS = [89, 127, 76];
const GRASS_LUSH = [61, 100, 68];
const GRASS_MOSS = [108, 139, 78];
const GRASS_DRY = [143, 151, 90];

export function createWorld(seed = (Math.random() * 1e9) | 0) {
  const noise = new Noise(seed);
  const rand = mulberry32(seed ^ 0x9e3779b9);
  const height = new Float32Array(GRID * GRID);
  const moisture = new Float32Array(GRID * GRID);
  const center = { x: HALF, y: HALF };

  const coastPhase = rand() * TAU;
  const pondAngle = rand() * TAU;
  const pondDist = 380 + rand() * 230;
  const pond = {
    x: center.x + Math.cos(pondAngle) * pondDist,
    y: center.y + Math.sin(pondAngle) * pondDist * 0.85,
    r: 82 + rand() * 48,
  };

  for (let gy = 0; gy < GRID; gy++) {
    const ny = (gy / (GRID - 1)) * 2 - 1;
    for (let gx = 0; gx < GRID; gx++) {
      const nx = (gx / (GRID - 1)) * 2 - 1;
      const ang = Math.atan2(ny, nx);
      const coast =
        0.79 +
        0.075 * Math.sin(ang * 3 + coastPhase) +
        0.05 * Math.sin(ang * 5 - coastPhase * 1.37) +
        0.035 * Math.sin(ang * 7 + coastPhase * 2.11) +
        0.06 * (noise.fbm(nx * 2.1 + 4.3, ny * 2.1 - 2.7, 3) - 0.5) * 2;
      const d = Math.hypot(nx, ny * 1.06);
      let e = (1 - d / coast) * 1.02;
      e += (noise.fbm(nx * 2.7 + 12.4, ny * 2.7 - 8.2, 4) - 0.5) * 0.34;
      e += (noise.fbm(nx * 6.4 - 3.7, ny * 6.4 + 6.1, 3) - 0.5) * 0.055;

      const wx = (gx / (GRID - 1)) * WORLD;
      const wy = (gy / (GRID - 1)) * WORLD;
      const pdx = wx - pond.x;
      const pdy = wy - pond.y;
      const pd = Math.hypot(pdx, pdy) / pond.r;
      if (pd < 1.45) e -= 0.95 * (1 - smoothstep(0.52, 1.45, pd));

      const idx = gy * GRID + gx;
      height[idx] = e;
      const m = noise.fbm(nx * 2.05 - 6.2, ny * 2.05 + 8.6, 3);
      moisture[idx] = clamp((m - 0.3) * 1.55 + 0.48 + (1 - clamp(e, 0, 1)) * 0.12, 0, 1);
    }
  }

  function sampleField(field, x, y) {
    const fx = clamp((x / WORLD) * (GRID - 1), 0, GRID - 1.001);
    const fy = clamp((y / WORLD) * (GRID - 1), 0, GRID - 1.001);
    const x0 = fx | 0;
    const y0 = fy | 0;
    const tx = fx - x0;
    const ty = fy - y0;
    const i0 = y0 * GRID + x0;
    const a = field[i0];
    const b = field[i0 + 1];
    const c = field[i0 + GRID];
    const d = field[i0 + GRID + 1];
    return lerp(lerp(a, b, tx), lerp(c, d, tx), ty);
  }

  const heightAt = (x, y) => sampleField(height, x, y);
  const moistureAt = (x, y) => sampleField(moisture, x, y);
  const isLand = (x, y, min = 0.015) =>
    x > 12 && y > 12 && x < WORLD - 12 && y < WORLD - 12 && heightAt(x, y) > min;

  /* ---------- painted terrain base ---------- */
  const BASE = 1024;
  const baseCanvas = document.createElement('canvas');
  baseCanvas.width = BASE;
  baseCanvas.height = BASE;
  const bctx = baseCanvas.getContext('2d');
  const img = bctx.createImageData(BASE, BASE);
  const data = img.data;

  for (let py = 0; py < BASE; py++) {
    const wy = (py / (BASE - 1)) * WORLD;
    for (let px = 0; px < BASE; px++) {
      const wx = (px / (BASE - 1)) * WORLD;
      const e = sampleField(height, wx, wy);
      const m = sampleField(moisture, wx, wy);
      let r, g, b;

      if (e < 0.012) {
        const deep = smoothstep(-0.62, -0.13, e);
        const shallow = smoothstep(-0.24, 0.012, e);
        r = lerp(lerp(WATER_DEEP[0], WATER_MID[0], deep), WATER_SHALLOW[0], shallow * 0.85);
        g = lerp(lerp(WATER_DEEP[1], WATER_MID[1], deep), WATER_SHALLOW[1], shallow * 0.85);
        b = lerp(lerp(WATER_DEEP[2], WATER_MID[2], deep), WATER_SHALLOW[2], shallow * 0.85);
        const w = (hash2(px >> 2, py >> 2, seed + 11) - 0.5) * 9;
        r += w;
        g += w;
        b += w;
        if (e > -0.045) {
          const f = smoothstep(-0.045, 0.012, e);
          r = lerp(r, FOAM[0], f * 0.42);
          g = lerp(g, FOAM[1], f * 0.42);
          b = lerp(b, FOAM[2], f * 0.42);
        }
      } else if (e < 0.088) {
        const t = smoothstep(0.012, 0.088, e);
        r = lerp(WET_SAND[0], SAND[0], t);
        g = lerp(WET_SAND[1], SAND[1], t);
        b = lerp(WET_SAND[2], SAND[2], t);
        if (e < 0.034) {
          const f = smoothstep(0.034, 0.012, e);
          r = lerp(r, FOAM[0], f * 0.5);
          g = lerp(g, FOAM[1], f * 0.5);
          b = lerp(b, FOAM[2], f * 0.5);
        } else {
          const dry = smoothstep(0.04, 0.09, e);
          r = lerp(r, SAND_LIGHT[0], dry * 0.5);
          g = lerp(g, SAND_LIGHT[1], dry * 0.5);
          b = lerp(b, SAND_LIGHT[2], dry * 0.5);
        }
        const w = (hash2(px >> 1, py >> 1, seed + 23) - 0.5) * 7;
        r += w;
        g += w;
        b += w;
      } else {
        const t = smoothstep(0.088, 0.17, e);
        r = lerp(GRASS_EDGE[0], GRASS[0], t);
        g = lerp(GRASS_EDGE[1], GRASS[1], t);
        b = lerp(GRASS_EDGE[2], GRASS[2], t);
        const lush = smoothstep(0.28, 0.78, m);
        r = lerp(r, GRASS_LUSH[0], lush * 0.62);
        g = lerp(g, GRASS_LUSH[1], lush * 0.62);
        b = lerp(b, GRASS_LUSH[2], lush * 0.62);
        const dry = 1 - smoothstep(0.18, 0.5, m);
        r = lerp(r, GRASS_DRY[0], dry * 0.22);
        g = lerp(g, GRASS_DRY[1], dry * 0.22);
        b = lerp(b, GRASS_DRY[2], dry * 0.22);
        const high = smoothstep(0.32, 0.92, e);
        r = lerp(r, GRASS_MOSS[0], high * 0.2);
        g = lerp(g, GRASS_MOSS[1], high * 0.2);
        b = lerp(b, GRASS_MOSS[2], high * 0.2);
        const w = (hash2(px, py, seed + 37) - 0.5) * 9;
        r += w;
        g += w;
        b += w;
      }

      const i = (py * BASE + px) * 4;
      data[i] = clamp(r, 0, 255);
      data[i + 1] = clamp(g, 0, 255);
      data[i + 2] = clamp(b, 0, 255);
      data[i + 3] = 255;
    }
  }
  bctx.putImageData(img, 0, 0);

  // broad, soft watercolour mottling
  for (let i = 0; i < 220; i++) {
    const bx = rand() * BASE;
    const by = rand() * BASE;
    const wx = (bx / BASE) * WORLD;
    const wy = (by / BASE) * WORLD;
    const e = sampleField(height, wx, wy);
    const rad = 14 + rand() * 58;
    let col;
    if (e < 0.01) col = rand() < 0.5 ? WATER_MID : WATER_SHALLOW;
    else if (e < 0.09) col = rand() < 0.5 ? SAND : SAND_LIGHT;
    else col = rand() < 0.45 ? GRASS_LUSH : rand() < 0.5 ? GRASS_MOSS : GRASS_DRY;
    bctx.globalAlpha = 0.035 + rand() * 0.045;
    bctx.fillStyle = `rgb(${col[0]},${col[1]},${col[2]})`;
    bctx.beginPath();
    bctx.ellipse(bx, by, rad, rad * (0.55 + rand() * 0.6), rand() * TAU, 0, TAU);
    bctx.fill();
  }
  bctx.globalAlpha = 1;

  const terrain = document.createElement('canvas');
  terrain.width = WORLD;
  terrain.height = WORLD;
  const tctx = terrain.getContext('2d');
  tctx.imageSmoothingEnabled = true;
  tctx.imageSmoothingQuality = 'high';
  tctx.drawImage(baseCanvas, 0, 0, WORLD, WORLD);

  /* ---------- hand-painted detail pass ---------- */
  const detail = mulberry32(seed ^ 0x51ed270b);

  // soft shore foam and ripples
  for (let i = 0; i < 7200; i++) {
    const x = detail() * WORLD;
    const y = detail() * WORLD;
    const e = heightAt(x, y);
    if (e > -0.055 && e < 0.062) {
      const a = 0.1 + detail() * 0.3;
      tctx.strokeStyle = `rgba(232,241,224,${a})`;
      tctx.lineWidth = 0.7 + detail() * 1.4;
      tctx.beginPath();
      const rr = 1.5 + detail() * 5.5;
      tctx.arc(x, y, rr, Math.PI * (0.1 + detail() * 0.35), Math.PI * (0.6 + detail() * 0.45));
      tctx.stroke();
    } else if (e > -0.42 && e < -0.06) {
      const a = 0.035 + detail() * 0.075;
      tctx.strokeStyle = `rgba(220,238,226,${a})`;
      tctx.lineWidth = 0.6 + detail() * 1.2;
      const len = 3 + detail() * 12;
      const yy = y;
      tctx.beginPath();
      tctx.moveTo(x - len, yy);
      tctx.quadraticCurveTo(x, yy - 1.5 - detail() * 2, x + len, yy);
      tctx.stroke();
    }
  }

  // grass strokes
  for (let i = 0; i < 17500; i++) {
    const x = detail() * WORLD;
    const y = detail() * WORLD;
    const e = heightAt(x, y);
    if (e < 0.1) continue;
    const m = moistureAt(x, y);
    const lush = m > 0.52;
    const roll = detail();
    let col;
    if (roll < 0.42) col = lush ? '86,124,68' : '112,138,76';
    else if (roll < 0.76) col = lush ? '61,99,63' : '132,146,84';
    else col = lush ? '111,142,82' : '150,155,96';
    const a = 0.12 + detail() * 0.22;
    const len = 1.8 + detail() * 4.2;
    const lean = (detail() - 0.5) * 3;
    tctx.strokeStyle = `rgba(${col},${a})`;
    tctx.lineWidth = 0.6 + detail() * 0.9;
    tctx.beginPath();
    tctx.moveTo(x, y);
    tctx.quadraticCurveTo(x + lean * 0.4, y - len * 0.55, x + lean, y - len);
    tctx.stroke();
  }

  // flower clusters
  const flowerCols = ['238,230,201', '222,197,132', '212,168,155', '232,226,214'];
  for (let i = 0; i < 280; i++) {
    const cx = detail() * WORLD;
    const cy = detail() * WORLD;
    if (heightAt(cx, cy) < 0.13) continue;
    const count = 2 + ((detail() * 5) | 0);
    const col = flowerCols[(detail() * flowerCols.length) | 0];
    for (let j = 0; j < count; j++) {
      const x = cx + (detail() - 0.5) * 18;
      const y = cy + (detail() - 0.5) * 16;
      tctx.fillStyle = `rgba(${col},${0.35 + detail() * 0.4})`;
      tctx.beginPath();
      tctx.arc(x, y, 0.7 + detail() * 1.1, 0, TAU);
      tctx.fill();
    }
  }

  // pebbles on the sand
  for (let i = 0; i < 850; i++) {
    const x = detail() * WORLD;
    const y = detail() * WORLD;
    const e = heightAt(x, y);
    if (e < 0.015 || e > 0.1) continue;
    tctx.fillStyle = `rgba(${110 + ((detail() * 35) | 0)},${104 + ((detail() * 30) | 0)},${90 + ((detail() * 30) | 0)},${0.18 + detail() * 0.28})`;
    tctx.beginPath();
    tctx.ellipse(x, y, 0.7 + detail() * 1.6, 0.5 + detail() * 1.1, detail() * TAU, 0, TAU);
    tctx.fill();
  }

  // fallen leaves and dry twigs
  for (let i = 0; i < 1200; i++) {
    const x = detail() * WORLD;
    const y = detail() * WORLD;
    if (heightAt(x, y) < 0.12) continue;
    const warm = detail() < 0.55;
    tctx.strokeStyle = warm
      ? `rgba(${126 + ((detail() * 30) | 0)},${101 + ((detail() * 25) | 0)},62,${0.12 + detail() * 0.18})`
      : `rgba(76,104,64,${0.1 + detail() * 0.16})`;
    tctx.lineWidth = 0.7;
    tctx.beginPath();
    const ang = detail() * TAU;
    const len = 1.2 + detail() * 2.6;
    tctx.moveTo(x, y);
    tctx.lineTo(x + Math.cos(ang) * len, y + Math.sin(ang) * len);
    tctx.stroke();
  }

  // gentle paths radiating from the starting clearing
  const pathRand = mulberry32(seed ^ 0x2a1b3c4d);
  for (let p = 0; p < 3; p++) {
    const ang = pathRand() * TAU;
    let px = center.x;
    let py = center.y;
    for (let s = 0; s < 34; s++) {
      const wob = (pathRand() - 0.5) * 0.5;
      px += Math.cos(ang + wob) * 22;
      py += Math.sin(ang + wob) * 22;
      if (!isLand(px, py, 0.09)) break;
      tctx.fillStyle = `rgba(203,187,146,${0.035 + pathRand() * 0.035})`;
      tctx.beginPath();
      tctx.ellipse(px, py, 12 + pathRand() * 9, 7 + pathRand() * 6, ang + wob, 0, TAU);
      tctx.fill();
    }
  }

  /* ---------- water sparkle points (animated at runtime) ---------- */
  const sparkles = [];
  for (let i = 0; i < 1100; i++) {
    const x = detail() * WORLD;
    const y = detail() * WORLD;
    const e = heightAt(x, y);
    if (e > 0.008 || e < -0.36) continue;
    sparkles.push({
      x,
      y,
      len: 2 + detail() * 8,
      phase: detail() * TAU,
      speed: 0.4 + detail() * 0.9,
      a: 0.04 + detail() * 0.1,
    });
  }

  /* ---------- objects ---------- */
  const objects = [];
  const fires = [];
  const placed = [];
  let nextId = 1;

  function addObject(kind, x, y, scale) {
    const meta = RESOURCE_META[kind];
    const obj = {
      id: nextId++,
      kind,
      x,
      y,
      scale,
      seed: (rand() * 1e9) | 0,
      ready: true,
      hits: meta.hits,
      maxHits: meta.hits,
      respawnAt: 0,
      growth: 1,
      sway: rand() * TAU,
    };
    objects.push(obj);
    placed.push({ x, y, r: meta.radius * scale });
    return obj;
  }

  function canPlace(x, y, minE, clearance) {
    if (!isLand(x, y, minE)) return false;
    for (const p of placed) {
      const dx = p.x - x;
      const dy = p.y - y;
      if (dx * dx + dy * dy < (p.r + clearance) * (p.r + clearance)) return false;
    }
    const dsx = x - center.x;
    const dsy = y - center.y;
    if (dsx * dsx + dsy * dsy < 135 * 135) return false;
    return true;
  }

  function findTutorialSpot(kind, angle, dist, minE) {
    const meta = RESOURCE_META[kind];
    for (let ring = 0; ring < 12; ring++) {
      const d = dist + ring * 26;
      for (let k = 0; k < 14; k++) {
        const a = angle + (k % 2 === 0 ? 1 : -1) * Math.ceil(k / 2) * 0.24;
        const x = center.x + Math.cos(a) * d;
        const y = center.y + Math.sin(a) * d;
        if (canPlace(x, y, minE, meta.radius + 10)) return { x, y };
      }
    }
    return null;
  }

  // a welcoming clearing: fire + one of each resource within easy reach
  let fireSpot = { x: center.x + 54, y: center.y + 38 };
  if (!isLand(fireSpot.x, fireSpot.y, 0.15)) fireSpot = { x: center.x + 40, y: center.y - 40 };
  fires.push({ id: 1, x: fireSpot.x, y: fireSpot.y, seed: (rand() * 1e9) | 0, builtAt: 0, starter: true });
  placed.push({ x: fireSpot.x, y: fireSpot.y, r: 26 });

  const tutorials = [
    ['tree', -0.6, 208, 0.15],
    ['bush', 2.45, 186, 0.13],
    ['rock', 1.35, 226, 0.09],
  ];
  for (const [kind, angle, dist, minE] of tutorials) {
    const spot = findTutorialSpot(kind, angle, dist, minE);
    if (spot) addObject(kind, spot.x, spot.y, 0.95 + rand() * 0.15);
  }

  function scatter(kind, target, candidates, minE, clearance, scoreFn) {
    const picks = [];
    for (let i = 0; i < candidates; i++) {
      const x = 90 + rand() * (WORLD - 180);
      const y = 90 + rand() * (WORLD - 180);
      if (!isLand(x, y, minE)) continue;
      const dsx = x - center.x;
      const dsy = y - center.y;
      if (dsx * dsx + dsy * dsy < 165 * 165) continue;
      picks.push({ x, y, score: scoreFn(x, y) });
    }
    picks.sort((a, b) => b.score - a.score);
    let added = 0;
    for (const p of picks) {
      if (added >= target) break;
      if (!canPlace(p.x, p.y, minE, clearance)) continue;
      addObject(kind, p.x, p.y, 0.82 + rand() * 0.42);
      added++;
    }
    return added;
  }

  scatter(
    'tree',
    66,
    480,
    0.16,
    58,
    (x, y) => noise.fbm(x / 640 + 3.1, y / 640 - 1.4, 3) * 1.1 + rand() * 0.45,
  );
  scatter(
    'rock',
    30,
    260,
    0.055,
    72,
    (x, y) => rand() * 0.8 + (1 - Math.abs(heightAt(x, y) - 0.22)) * 0.4,
  );
  scatter(
    'bush',
    38,
    300,
    0.105,
    46,
    (x, y) => moistureAt(x, y) * 0.9 + rand() * 0.5,
  );

  return {
    seed,
    terrain,
    height,
    moisture,
    heightAt,
    moistureAt,
    isLand,
    center,
    spawn: { x: center.x, y: center.y },
    pond,
    objects,
    fires,
    sparkles,
    addFire(x, y) {
      const fire = {
        id: fires.length + 1,
        x,
        y,
        seed: (Math.random() * 1e9) | 0,
        builtAt: performance.now() / 1000,
      };
      fires.push(fire);
      return fire;
    },
    findFireSpot(px, py, dir) {
      for (let ring = 0; ring < 9; ring++) {
        const dist = 44 + ring * 12;
        for (let k = 0; k < 10; k++) {
          const a = dir + (k % 2 === 0 ? 1 : -1) * Math.ceil(k / 2) * 0.5;
          const x = clamp(px + Math.cos(a) * dist, 40, WORLD - 40);
          const y = clamp(py + Math.sin(a) * dist, 40, WORLD - 40);
          if (!isLand(x, y, 0.085)) continue;
          let ok = true;
          for (const o of objects) {
            const dx = o.x - x;
            const dy = o.y - y;
            if (dx * dx + dy * dy < 48 * 48) { ok = false; break; }
          }
          if (ok) {
            for (const f of fires) {
              const dx = f.x - x;
              const dy = f.y - y;
              if (dx * dx + dy * dy < 110 * 110) { ok = false; break; }
            }
          }
          if (ok) return { x, y };
        }
      }
      return null;
    },
  };
}

import { TAU, mulberry32, clamp, lerp } from './util.js';

function smoothBlob(ctx, seed, radius, points = 9, wobble = 0.24) {
  const rnd = mulberry32(seed);
  const pts = [];
  for (let i = 0; i < points; i++) {
    const a = (i / points) * TAU + (rnd() - 0.5) * 0.16;
    const r = radius * (1 - wobble * 0.5 + rnd() * wobble);
    pts.push({ x: Math.cos(a) * r, y: Math.sin(a) * r });
  }
  ctx.beginPath();
  let mx = (pts[points - 1].x + pts[0].x) / 2;
  let my = (pts[points - 1].y + pts[0].y) / 2;
  ctx.moveTo(mx, my);
  for (let i = 0; i < points; i++) {
    const p = pts[i];
    const n = pts[(i + 1) % points];
    mx = (p.x + n.x) / 2;
    my = (p.y + n.y) / 2;
    ctx.quadraticCurveTo(p.x, p.y, mx, my);
  }
  ctx.closePath();
}

function pineStar(ctx, seed, radius, spikes = 11) {
  const rnd = mulberry32(seed);
  const total = spikes * 2;
  ctx.beginPath();
  for (let i = 0; i <= total; i++) {
    const a = (i / total) * TAU + (rnd() - 0.5) * 0.06;
    const long = i % 2 === 0;
    const r = radius * (long ? 0.94 + rnd() * 0.14 : 0.66 + rnd() * 0.12);
    const x = Math.cos(a) * r;
    const y = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

export function drawPine(ctx, o, time) {
  const s = o.scale;
  ctx.fillStyle = 'rgba(17,38,27,.2)';
  ctx.beginPath();
  ctx.ellipse(o.x + 7 * s, o.y + 9 * s, 21 * s, 8 * s, 0.08, 0, TAU);
  ctx.fill();

  ctx.fillStyle = '#6b5138';
  ctx.beginPath();
  ctx.ellipse(o.x + 1.5 * s, o.y + 5.5 * s, 3.3 * s, 4.4 * s, 0, 0, TAU);
  ctx.fill();

  if (!o.ready) {
    // stump
    ctx.fillStyle = '#7a5d3f';
    ctx.beginPath();
    ctx.ellipse(o.x, o.y + 1 * s, 8 * s, 6.5 * s, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#c3a679';
    ctx.beginPath();
    ctx.ellipse(o.x, o.y - 0.5 * s, 7.1 * s, 5.6 * s, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(116,87,55,.5)';
    ctx.lineWidth = 0.8 * s;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.ellipse(o.x, o.y - 0.5 * s, (2.2 + i * 2.1) * s, (1.6 + i * 1.6) * s, 0, 0, TAU);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(77,105,62,.8)';
    ctx.beginPath();
    ctx.ellipse(o.x - 9 * s, o.y + 3 * s, 5 * s, 2.6 * s, -0.3, 0, TAU);
    ctx.fill();
    return;
  }

  const g = o.growth ?? 1;
  const sway = Math.sin(time * 0.62 + o.sway) * 0.028 + Math.sin(time * 0.23 + o.sway * 2) * 0.012;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.rotate(sway);
  ctx.scale(g, g);

  // outer needles
  ctx.fillStyle = '#294c35';
  pineStar(ctx, o.seed, 27 * s, 11);
  ctx.fill();

  // mid canopy
  ctx.save();
  ctx.rotate(0.28);
  ctx.fillStyle = '#3b6643';
  pineStar(ctx, o.seed + 17, 21 * s, 9);
  ctx.fill();
  ctx.restore();

  // lit crown
  ctx.save();
  ctx.translate(-1.6 * s, -2.4 * s);
  ctx.rotate(-0.18);
  ctx.fillStyle = '#537e4b';
  pineStar(ctx, o.seed + 43, 14 * s, 8);
  ctx.fill();
  ctx.restore();

  // needle strokes
  const rnd = mulberry32(o.seed + 5);
  ctx.strokeStyle = 'rgba(25,55,36,.34)';
  ctx.lineWidth = 0.8 * s;
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU + rnd() * 0.2;
    const r0 = 6 * s;
    const r1 = (16 + rnd() * 9) * s;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
    ctx.lineTo(Math.cos(a + 0.05) * r1, Math.sin(a + 0.05) * r1);
    ctx.stroke();
  }

  // soft light
  ctx.fillStyle = 'rgba(160,186,111,.17)';
  ctx.beginPath();
  ctx.ellipse(-5.5 * s, -7 * s, 8 * s, 4.8 * s, -0.6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(228,232,190,.12)';
  ctx.beginPath();
  ctx.ellipse(-7.5 * s, -9 * s, 3.4 * s, 1.9 * s, -0.7, 0, TAU);
  ctx.fill();

  ctx.restore();
}

export function drawRock(ctx, o, time) {
  const s = o.scale;
  ctx.fillStyle = 'rgba(23,39,30,.22)';
  ctx.beginPath();
  ctx.ellipse(o.x + 5 * s, o.y + 6 * s, 17 * s, 7 * s, 0.06, 0, TAU);
  ctx.fill();

  if (!o.ready) {
    for (let i = 0; i < 3; i++) {
      const a = i * 2.1 + o.seed;
      const r = 6 + i * 2.2;
      const px = o.x + Math.cos(a) * 8 * s;
      const py = o.y + Math.sin(a) * 5 * s;
      ctx.fillStyle = i === 0 ? '#8f8d7a' : '#777a6b';
      smoothBlob(ctx, o.seed + i * 13, r * 0.55 * s, 6, 0.3);
      ctx.save();
      ctx.translate(px, py);
      ctx.fill();
      ctx.restore();
    }
    return;
  }

  const g = o.growth ?? 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.scale(g, g);

  const r = 17 * s;
  const grad = ctx.createLinearGradient(-r, -r, r * 0.9, r);
  grad.addColorStop(0, '#a9a48f');
  grad.addColorStop(0.5, '#8b8b78');
  grad.addColorStop(1, '#636a5e');
  ctx.fillStyle = grad;
  smoothBlob(ctx, o.seed, r, 9, 0.3);
  ctx.fill();
  ctx.strokeStyle = 'rgba(59,68,58,.35)';
  ctx.lineWidth = 0.9 * s;
  ctx.stroke();

  // moss
  ctx.fillStyle = 'rgba(109,137,82,.6)';
  ctx.beginPath();
  ctx.ellipse(-r * 0.28, -r * 0.36, r * 0.4, r * 0.22, -0.5, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(126,150,92,.35)';
  ctx.beginPath();
  ctx.ellipse(-r * 0.05, -r * 0.52, r * 0.22, r * 0.12, 0.2, 0, TAU);
  ctx.fill();

  // top light
  ctx.strokeStyle = 'rgba(226,222,200,.35)';
  ctx.lineWidth = 1.4 * s;
  ctx.beginPath();
  ctx.arc(-r * 0.12, -r * 0.1, r * 0.66, Math.PI * 1.06, Math.PI * 1.55);
  ctx.stroke();

  // cracks
  ctx.strokeStyle = 'rgba(63,69,59,.4)';
  ctx.lineWidth = 0.8 * s;
  ctx.beginPath();
  ctx.moveTo(-r * 0.15, -r * 0.1);
  ctx.lineTo(r * 0.05, r * 0.2);
  ctx.lineTo(r * 0.26, r * 0.28);
  ctx.moveTo(r * 0.05, r * 0.2);
  ctx.lineTo(r * 0.12, r * 0.46);
  ctx.stroke();

  // tiny grass at base
  ctx.strokeStyle = 'rgba(87,119,69,.7)';
  ctx.lineWidth = 0.8 * s;
  for (let i = 0; i < 4; i++) {
    const a = 0.4 + i * 0.5;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * r * 0.85, Math.sin(a) * r * 0.7);
    ctx.lineTo(Math.cos(a) * r * 1.06, Math.sin(a) * r * 0.95);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawBush(ctx, o, time) {
  const s = o.scale;
  ctx.fillStyle = 'rgba(20,40,27,.2)';
  ctx.beginPath();
  ctx.ellipse(o.x + 5 * s, o.y + 7 * s, 17 * s, 7 * s, 0.08, 0, TAU);
  ctx.fill();

  const g = o.growth ?? 1;
  const sway = Math.sin(time * 0.8 + o.sway) * 0.02;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.rotate(sway);
  ctx.scale(g, g);

  const ready = o.ready;
  const blobs = [
    [-7, 2, 10.5, '#3c6745'],
    [6, 1, 10.8, '#456f47'],
    [0, -6, 11.5, '#4d7849'],
    [-1, 7, 9.4, '#35603f'],
    [9, 7, 7.4, '#3c6745'],
  ];
  for (let i = 0; i < blobs.length; i++) {
    const [bx, by, br, col] = blobs[i];
    ctx.fillStyle = ready ? col : '#54714e';
    smoothBlob(ctx, o.seed + i * 31, br * s, 8, 0.34);
    ctx.save();
    ctx.translate(bx * s, by * s);
    ctx.fill();
    ctx.restore();
  }

  // leaf highlights
  const rnd = mulberry32(o.seed + 7);
  ctx.strokeStyle = ready ? 'rgba(129,160,94,.5)' : 'rgba(139,151,112,.4)';
  ctx.lineWidth = 0.9 * s;
  for (let i = 0; i < 10; i++) {
    const a = rnd() * TAU;
    const r0 = 4 + rnd() * 8;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * r0 * s, Math.sin(a) * r0 * s);
    ctx.lineTo(Math.cos(a + 0.3) * (r0 + 5) * s, Math.sin(a + 0.3) * (r0 + 5) * s);
    ctx.stroke();
  }

  if (ready) {
    const berries = 8;
    for (let i = 0; i < berries; i++) {
      const a = (i / berries) * TAU + o.seed * 0.001;
      const rr = 4 + rnd() * 9;
      const bx = Math.cos(a) * rr * s;
      const by = Math.sin(a) * rr * s - 2 * s;
      ctx.fillStyle = i % 3 === 0 ? '#c96358' : '#ad4a43';
      ctx.beginPath();
      ctx.arc(bx, by, 2.2 * s, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(246,196,172,.6)';
      ctx.beginPath();
      ctx.arc(bx - 0.6 * s, by - 0.7 * s, 0.75 * s, 0, TAU);
      ctx.fill();
    }
  } else {
    ctx.strokeStyle = 'rgba(91,112,75,.55)';
    ctx.lineWidth = 0.8 * s;
    for (let i = 0; i < 5; i++) {
      const a = rnd() * TAU;
      ctx.beginPath();
      ctx.moveTo(0, 2 * s);
      ctx.lineTo(Math.cos(a) * 12 * s, Math.sin(a) * 9 * s);
      ctx.stroke();
    }
  }
  ctx.restore();
}

export function drawFireGlow(ctx, fire, time, strength = 1) {
  const flicker = 0.9 + Math.sin(time * 7.3 + fire.seed) * 0.05 + Math.sin(time * 13.1 + fire.seed * 0.3) * 0.03;
  const r = 250 * flicker;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const grad = ctx.createRadialGradient(fire.x, fire.y - 4, 4, fire.x, fire.y - 4, r);
  grad.addColorStop(0, `rgba(255,190,108,${0.22 * strength})`);
  grad.addColorStop(0.32, `rgba(240,150,76,${0.12 * strength})`);
  grad.addColorStop(0.68, `rgba(214,116,58,${0.045 * strength})`);
  grad.addColorStop(1, 'rgba(200,100,50,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(fire.x, fire.y - 4, r, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawCampfire(ctx, fire, time, night = 0) {
  const s = 1;
  ctx.fillStyle = 'rgba(21,35,25,.22)';
  ctx.beginPath();
  ctx.ellipse(fire.x + 3, fire.y + 7, 22, 8, 0, 0, TAU);
  ctx.fill();

  // stone ring
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2;
    const px = fire.x + Math.cos(a) * 18;
    const py = fire.y + Math.sin(a) * 10.5;
    ctx.fillStyle = i % 2 ? '#8f8d7b' : '#a09d89';
    ctx.beginPath();
    ctx.ellipse(px, py, 4.2, 3.2, a, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(230,226,203,.18)';
    ctx.beginPath();
    ctx.ellipse(px - 0.8, py - 0.9, 1.6, 1, a, 0, TAU);
    ctx.fill();
  }

  // logs
  ctx.save();
  ctx.translate(fire.x, fire.y + 1);
  ctx.rotate(0.45);
  ctx.fillStyle = '#5c4430';
  roundRect(ctx, -13, -3, 26, 6, 3);
  ctx.fill();
  ctx.fillStyle = '#75573d';
  roundRect(ctx, -13, -3, 26, 2.6, 1.4);
  ctx.fill();
  ctx.rotate(-0.9);
  ctx.fillStyle = '#533d2c';
  roundRect(ctx, -12, -2.8, 24, 5.6, 2.8);
  ctx.fill();
  ctx.restore();

  // ember bed
  ctx.fillStyle = `rgba(238,128,58,${0.4 + night * 0.25})`;
  ctx.beginPath();
  ctx.ellipse(fire.x, fire.y + 1, 7.5, 3.6, 0, 0, TAU);
  ctx.fill();

  const f = 1 + Math.sin(time * 9 + fire.seed) * 0.08 + Math.sin(time * 15.7 + fire.seed * 0.4) * 0.05;
  const sway = Math.sin(time * 6.2 + fire.seed) * 1.4;
  ctx.save();
  ctx.translate(fire.x + sway * 0.3, fire.y - 4);

  // outer flame
  flamePath(ctx, 10 * f, 30 * f, sway);
  ctx.fillStyle = `rgba(226,112,54,${0.88})`;
  ctx.fill();
  // mid
  ctx.save();
  ctx.translate(0, 3);
  flamePath(ctx, 7.2 * f, 22 * f, sway * 0.7);
  ctx.fillStyle = 'rgba(242,166,72,.94)';
  ctx.fill();
  // core
  ctx.translate(0, 3.5);
  flamePath(ctx, 4.2 * f, 13 * f, sway * 0.45);
  ctx.fillStyle = 'rgba(255,226,151,.96)';
  ctx.fill();
  ctx.restore();

  // hot tip
  ctx.fillStyle = 'rgba(255,246,205,.8)';
  ctx.beginPath();
  ctx.ellipse(sway * 0.4, -17 * f, 1.7, 4.4, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  if (night > 0.15) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = `rgba(255,196,116,${0.08 * night})`;
    ctx.beginPath();
    ctx.arc(fire.x, fire.y - 6, 42, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
}

function flamePath(ctx, w, h, sway) {
  ctx.beginPath();
  ctx.moveTo(0, 2);
  ctx.bezierCurveTo(w, -h * 0.12, w * 0.82 + sway, -h * 0.58, sway * 0.6, -h);
  ctx.bezierCurveTo(-w * 0.82 + sway, -h * 0.58, -w, -h * 0.12, 0, 2);
  ctx.closePath();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

export function drawPlayer(ctx, p, time, night = 0) {
  const walking = p.moving ? 1 : 0;
  const bob = walking ? Math.sin(time * 11.5) * 1.5 : Math.sin(time * 2.1) * 0.55;
  const dir = p.dir;
  const step = walking ? Math.sin(time * 11.5) * 3.1 : 0;

  // shadow
  ctx.fillStyle = 'rgba(16,34,26,.28)';
  ctx.beginPath();
  ctx.ellipse(p.x + 1.5, p.y + 8, 11.5, 4.8, 0, 0, TAU);
  ctx.fill();

  if (night > 0.2) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, 34);
    g.addColorStop(0, `rgba(255,214,150,${0.1 * night})`);
    g.addColorStop(1, 'rgba(255,200,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 34, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.rotate(dir);

  // feet
  ctx.fillStyle = '#3a4d3d';
  ctx.beginPath();
  ctx.ellipse(0, 8 + step * 0.35, 3.1, 2.1, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(0, -8 - step * 0.35, 3.1, 2.1, 0, 0, TAU);
  ctx.fill();

  // scarf tail
  ctx.fillStyle = '#bd745a';
  ctx.beginPath();
  ctx.moveTo(-5, -3.4);
  ctx.quadraticCurveTo(-12 - Math.sin(time * 9) * 1.2, -1.2, -9.5, 2.6);
  ctx.quadraticCurveTo(-7.5, 0.2, -5, 1.2);
  ctx.closePath();
  ctx.fill();

  // backpack
  ctx.fillStyle = '#85633f';
  roundRect(ctx, -11.5, -5.6, 6.4, 11.2, 3.1);
  ctx.fill();
  ctx.fillStyle = '#6e5034';
  roundRect(ctx, -11.5, -5.6, 2.3, 11.2, 1.1);
  ctx.fill();

  // cloak
  const cloak = ctx.createRadialGradient(-2, -3, 1, 0, 0, 13);
  cloak.addColorStop(0, '#f7efdb');
  cloak.addColorStop(0.7, '#e9dec4');
  cloak.addColorStop(1, '#d4c6a6');
  ctx.fillStyle = cloak;
  ctx.beginPath();
  ctx.ellipse(0, 0, 10.2, 11.2, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(74,92,70,.55)';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // hood collar
  ctx.strokeStyle = 'rgba(75,101,77,.7)';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(0.5, 0, 8.4, -1.15, 1.15);
  ctx.stroke();

  // hands
  ctx.fillStyle = '#e8c7a2';
  ctx.beginPath();
  ctx.arc(4.5, 8.6, 2.1, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(4.5, -8.6, 2.1, 0, TAU);
  ctx.fill();

  // head
  ctx.fillStyle = '#4a382c';
  ctx.beginPath();
  ctx.arc(2.4, 0, 6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#eac9a4';
  ctx.beginPath();
  ctx.arc(4.5, 0, 3.7, -1.25, 1.25);
  ctx.closePath();
  ctx.fill();

  // hood highlight
  ctx.strokeStyle = 'rgba(246,239,218,.45)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(2.4, 0, 6, -2.6, -1.5);
  ctx.stroke();

  // scarf knot at the front
  ctx.fillStyle = '#c97a5e';
  ctx.beginPath();
  ctx.ellipse(6.7, 0, 2.6, 3.2, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(246,210,180,.4)';
  ctx.beginPath();
  ctx.ellipse(6.4, -0.7, 1, 1.2, 0, 0, TAU);
  ctx.fill();

  ctx.restore();
}

export function drawTargetRing(ctx, o, time) {
  const meta = o.scale;
  const r = 29 * meta;
  ctx.save();
  ctx.translate(o.x, o.y + 3);
  ctx.strokeStyle = 'rgba(255,247,225,.42)';
  ctx.lineWidth = 1.4;
  ctx.setLineDash([4, 7]);
  ctx.lineDashOffset = -time * 16;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.strokeStyle = 'rgba(255,247,225,.1)';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

export function drawSparkles(ctx, sparkles, view, time) {
  ctx.save();
  for (const s of sparkles) {
    if (s.x < view.x1 || s.x > view.x2 || s.y < view.y1 || s.y > view.y2) continue;
    const pulse = 0.5 + 0.5 * Math.sin(time * s.speed + s.phase);
    ctx.globalAlpha = s.a * (0.3 + pulse * 0.7);
    ctx.strokeStyle = 'rgba(230,244,233,1)';
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    const y = s.y + Math.sin(time * 0.5 + s.phase) * 1.5;
    ctx.moveTo(s.x - s.len * 0.5, y);
    ctx.quadraticCurveTo(s.x, y - 1.6, s.x + s.len * 0.5, y);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawFirefly(ctx, f, time) {
  const pulse = 0.55 + 0.45 * Math.sin(time * f.speed + f.phase);
  const a = f.alpha * pulse;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = `rgba(214,240,150,${a * 0.13})`;
  ctx.beginPath();
  ctx.arc(f.x, f.y, 7, 0, TAU);
  ctx.fill();
  ctx.fillStyle = `rgba(236,252,184,${a})`;
  ctx.beginPath();
  ctx.arc(f.x, f.y, 1.5, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawParticle(ctx, p) {
  const life = clamp(p.life / p.maxLife, 0, 1);
  ctx.save();
  ctx.globalAlpha = life * (p.alpha ?? 0.9);
  ctx.fillStyle = p.color;
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot || 0);
  if (p.shape === 'leaf') {
    ctx.beginPath();
    ctx.ellipse(0, 0, p.size, p.size * 0.46, 0, 0, TAU);
    ctx.fill();
  } else if (p.shape === 'spark') {
    ctx.fillRect(-p.size * 0.5, -p.size * 0.5, p.size, p.size);
  } else {
    ctx.beginPath();
    ctx.arc(0, 0, p.size, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawDarkness(ctx, lightCanvas, darkness, playerScreen, radius, firesScreen, time, viewW, viewH) {
  const lctx = lightCanvas.getContext('2d');
  lctx.setTransform(1, 0, 0, 1, 0, 0);
  lctx.clearRect(0, 0, viewW, viewH);
  const alpha = 0.84 * Math.pow(darkness, 0.92);
  lctx.fillStyle = `rgba(7,16,40,${alpha})`;
  lctx.fillRect(0, 0, viewW, viewH);
  lctx.globalCompositeOperation = 'destination-out';

  function punch(x, y, r, strength = 1) {
    const g = lctx.createRadialGradient(x, y, r * 0.12, x, y, r);
    g.addColorStop(0, `rgba(0,0,0,${strength})`);
    g.addColorStop(0.55, `rgba(0,0,0,${strength * 0.88})`);
    g.addColorStop(0.82, `rgba(0,0,0,${strength * 0.35})`);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    lctx.fillStyle = g;
    lctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  punch(playerScreen.x, playerScreen.y, radius, 1);
  for (const f of firesScreen) {
    punch(f.x, f.y, f.r, 1);
  }

  lctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(lightCanvas, 0, 0, viewW, viewH);
}

export class Soundscape {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.started = false;
    this.muted = false;
    this.timers = { bird: 4, cricket: 3, step: 0.2, pop: 0.4 };
    this.nearFire = 0;
    this.volume = 0.62;
  }

  async start() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') await this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = 0;
    this.master.connect(ctx.destination);

    // reusable soft noise
    const len = Math.floor(ctx.sampleRate * 2.2);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.985 + white * 0.015;
      data[i] = last * 4.5 + white * 0.14;
    }
    this.noise = buf;

    // wind
    const windSrc = ctx.createBufferSource();
    windSrc.buffer = buf;
    windSrc.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 430;
    windFilter.Q.value = 0.4;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.05;
    windSrc.connect(windFilter).connect(windGain).connect(this.master);
    windSrc.start();
    this.wind = { filter: windFilter, gain: windGain };

    // distant surf
    const seaSrc = ctx.createBufferSource();
    seaSrc.buffer = buf;
    seaSrc.loop = true;
    const seaFilter = ctx.createBiquadFilter();
    seaFilter.type = 'bandpass';
    seaFilter.frequency.value = 260;
    seaFilter.Q.value = 0.6;
    const seaGain = ctx.createGain();
    seaGain.gain.value = 0.022;
    seaSrc.connect(seaFilter).connect(seaGain).connect(this.master);
    seaSrc.start();
    this.sea = { filter: seaFilter, gain: seaGain };

    // fire bed
    const fireSrc = ctx.createBufferSource();
    fireSrc.buffer = buf;
    fireSrc.loop = true;
    const fireFilter = ctx.createBiquadFilter();
    fireFilter.type = 'bandpass';
    fireFilter.frequency.value = 720;
    fireFilter.Q.value = 0.55;
    const fireGain = ctx.createGain();
    fireGain.gain.value = 0;
    fireSrc.connect(fireFilter).connect(fireGain).connect(this.master);
    fireSrc.start();
    this.fire = { filter: fireFilter, gain: fireGain };

    this.started = true;
    if (ctx.state === 'suspended') await ctx.resume();
    this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, ctx.currentTime, 0.8);
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(muted ? 0 : this.volume, this.ctx.currentTime, 0.15);
  }

  setPaused(paused) {
    if (!this.ctx) return;
    if (paused) this.ctx.suspend().catch(() => {});
    else this.ctx.resume().catch(() => {});
  }

  tone({ freq = 440, endFreq = null, dur = 0.15, gain = 0.03, type = 'sine', pan = 0, when = 0 }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.02, dur * 0.25));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    osc.connect(g).connect(p).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noiseBurst({ dur = 0.12, gain = 0.02, freq = 900, q = 0.8, type = 'bandpass', pan = 0, when = 0 }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    src.connect(f).connect(g).connect(p).connect(this.master);
    src.start(t, Math.random() * 1.4);
    src.stop(t + dur + 0.03);
  }

  bird() {
    if (!this.ctx) return;
    const pan = Math.random() * 1.4 - 0.7;
    const base = 1700 + Math.random() * 1300;
    const notes = 2 + ((Math.random() * 3) | 0);
    let when = 0;
    for (let i = 0; i < notes; i++) {
      const up = Math.random() > 0.45;
      this.tone({
        freq: base * (0.94 + Math.random() * 0.12),
        endFreq: base * (up ? 1.28 : 0.82),
        dur: 0.055 + Math.random() * 0.05,
        gain: 0.012 + Math.random() * 0.014,
        type: 'sine',
        pan,
        when,
      });
      when += 0.075 + Math.random() * 0.08;
    }
  }

  cricket() {
    const pan = Math.random() * 1.6 - 0.8;
    const base = 2350 + Math.random() * 650;
    const pulses = 3 + ((Math.random() * 3) | 0);
    let when = 0;
    for (let i = 0; i < pulses; i++) {
      this.tone({ freq: base, endFreq: base * 0.98, dur: 0.028, gain: 0.005, type: 'sine', pan, when });
      when += 0.055;
    }
  }

  crackle() {
    if (!this.ctx) return;
    this.noiseBurst({ dur: 0.035 + Math.random() * 0.05, gain: 0.01 + Math.random() * 0.02, freq: 1400 + Math.random() * 900, q: 1.2, pan: (Math.random() - 0.5) * 0.5 });
  }

  step() {
    this.noiseBurst({ dur: 0.09, gain: 0.006, freq: 380, q: 0.6, type: 'lowpass', pan: (Math.random() - 0.5) * 0.3 });
  }

  chop() {
    this.tone({ freq: 135, endFreq: 62, dur: 0.13, gain: 0.05, type: 'sine' });
    this.noiseBurst({ dur: 0.1, gain: 0.026, freq: 520, q: 0.7, type: 'lowpass' });
  }

  mine() {
    this.tone({ freq: 96, endFreq: 54, dur: 0.16, gain: 0.04, type: 'sine' });
    this.noiseBurst({ dur: 0.12, gain: 0.022, freq: 1900, q: 1.1 });
  }

  pick() {
    this.tone({ freq: 620, endFreq: 420, dur: 0.09, gain: 0.018, type: 'sine' });
    this.noiseBurst({ dur: 0.08, gain: 0.012, freq: 1200, q: 0.9 });
  }

  craft() {
    this.tone({ freq: 523, dur: 0.32, gain: 0.022, type: 'sine', when: 0 });
    this.tone({ freq: 784, dur: 0.4, gain: 0.016, type: 'sine', when: 0.09 });
    this.tone({ freq: 1046, dur: 0.34, gain: 0.009, type: 'sine', when: 0.17 });
  }

  build() {
    this.noiseBurst({ dur: 0.16, gain: 0.026, freq: 300, q: 0.7, type: 'lowpass' });
    this.tone({ freq: 180, endFreq: 110, dur: 0.18, gain: 0.035, type: 'sine' });
    this.craft();
  }

  eat() {
    this.tone({ freq: 340, endFreq: 250, dur: 0.1, gain: 0.02, type: 'sine' });
    this.noiseBurst({ dur: 0.08, gain: 0.012, freq: 700, q: 0.7, type: 'lowpass' });
  }

  faint() {
    this.tone({ freq: 220, endFreq: 110, dur: 1.4, gain: 0.025, type: 'sine' });
    this.tone({ freq: 330, endFreq: 165, dur: 1.6, gain: 0.012, type: 'sine', when: 0.1 });
  }

  wake() {
    this.tone({ freq: 392, dur: 0.4, gain: 0.02, type: 'sine' });
    this.tone({ freq: 523, dur: 0.5, gain: 0.014, type: 'sine', when: 0.14 });
  }

  update(dt, state) {
    if (!this.started || !this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const daylight = state.daylight ?? 1;
    const moving = state.moving;

    const windTarget = 0.038 + 0.016 * Math.sin(t * 0.14) + 0.01 * Math.sin(t * 0.037);
    this.wind.gain.gain.setTargetAtTime(windTarget, t, 0.5);
    this.wind.filter.frequency.setTargetAtTime(360 + 130 * (0.5 + 0.5 * Math.sin(t * 0.11)), t, 0.8);
    this.sea.gain.gain.setTargetAtTime(0.014 + 0.012 * (0.5 + 0.5 * Math.sin(t * 0.09 + 1.4)), t, 0.7);

    const fireTarget = state.nearFire ? 0.026 : 0;
    this.fire.gain.gain.setTargetAtTime(fireTarget, t, 0.4);

    this.timers.bird -= dt;
    this.timers.cricket -= dt;
    this.timers.step -= dt;
    this.timers.pop -= dt;

    if (this.timers.bird <= 0) {
      this.timers.bird = 6 + Math.random() * 12;
      if (daylight > 0.45) this.bird();
    }
    if (this.timers.cricket <= 0) {
      this.timers.cricket = 2.4 + Math.random() * 5;
      if (daylight < 0.3) this.cricket();
    }
    if (this.timers.pop <= 0) {
      this.timers.pop = 0.18 + Math.random() * 0.55;
      if (state.nearFire) this.crackle();
    }
    if (moving) {
      if (this.timers.step <= 0) {
        this.timers.step = 0.33;
        this.step();
      }
    } else {
      this.timers.step = 0.15;
    }
  }
}

content.text:
Now the main game.js. This is the most complex. Let's carefully plan and implement.

Imports:
```js
import { TAU, clamp, lerp, smoothstep } from './util.js';
import { createWorld, WORLD, RESOURCE_META } from './world.js';
import { drawPine, drawRock, drawBush, drawFireGlow, drawCampfire, drawPlayer, drawTargetRing, drawSparkles, drawFirefly, drawParticle, drawDarkness } from './art.js';
import { Soundscape } from './audio.js';
```

Constants:
```js
const DAY_LENGTH = 300; // seconds
const START_TIME = 0.13;
const MAX_DPR = 2;
```

State:
```js
const state = {
  started:false, paused:false, fainting:false, uiOpen:false,
  time: START_TIME, day:1,
  player:{x,y,dir:-PI/2,moving:false,stamina...},
  cam:{x,y},
  inventory:{wood:0,stone:0,food:0},
  tools:{axe:false,pick:false},
  survival:{health:100,hunger:100,stamina:100},
  nearFire:false,
  target:null,
  actionHeld:false,
  gather:{targetId:0, progress:0},
  toasts:[],
  nightShown:false,
  ...
};
```

DOM refs.

Setup:
