Target detection:
```js
function findTarget(){
 let best=null, bestD=Infinity;
 for (const o of world.objects) {
  if(!o.ready) continue;
  const meta=RESOURCE_META[o.kind];
  const dx=o.x-p.x, dy=o.y-p.y;
  const d2=dx*dx+dy*dy;
  if(d2 < meta.reach*meta.reach && d2<bestD){best=o;bestD=d2;}
 }
 return best;
}
```
