await page.waitForTimeout(300);
await page.locator('[data-craft="campfire"]').click();
await page.waitForTimeout(500);
console.log('after craft', await page.evaluate(() => window.__nova.info()));

// night away from fire
await page.evaluate(() => { window.__nova.closeCraft(); const p = window.__nova.state.player; window.__nova.teleport(p.x + 600, p.y + 300); window.__nova.setNight(); window.__nova.refill(); });
await page.waitForTimeout(700);
await page.screenshot({ path: join(out, 'night-away.jpg'), type: 'jpeg', quality: 82 });
