export function drawPlayer(ctx, p, time, night = 0) {
  const walking = p.moving;
  const bob = walking ? Math.sin(time * 11.5) * 1.6 : Math.sin(time * 2.1) * 0.6;
  const dir = p.dir;
  const step = walking ? Math.sin(time * 11.5) * 3.4 : 0;

  // shadow
  ctx.fillStyle = 'rgba(16,34,26,.3)';
  ctx.beginPath();
  ctx.ellipse(p.x + 1.5, p.y + 9, 13, 5.4, 0, 0, TAU);
  ctx.fill();

  if (night > 0.2) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, 42);
    g.addColorStop(0, `rgba(255,214,150,${0.12 * night})`);
    g.addColorStop(1, 'rgba(255,200,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 42, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.rotate(dir);

  // feet
  ctx.fillStyle = '#394c3c';
  ctx.beginPath();
  ctx.ellipse(step * 0.5, 8.2, 3.4, 2.3, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(-step * 0.5, -8.2, 3.4, 2.3, 0, 0, TAU);
  ctx.fill();

  // scarf tail
  ctx.fillStyle = '#b96f56';
  ctx.beginPath();
  ctx.moveTo(-4.5, -3.6);
  ctx.quadraticCurveTo(-13 - Math.sin(time * 9) * 1.4, -2.2, -11, 3.2);
  ctx.quadraticCurveTo(-8, 0.4, -4.5, 1.6);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(232,164,132,.4)';
  ctx.beginPath();
  ctx.ellipse(-8, 0.3, 2.4, 0.8, 0.3, 0, TAU);
  ctx.fill();

  // backpack
  ctx.fillStyle = '#876440';
  roundRect(ctx, -13.4, -6.4, 7.2, 12.8, 3.6);
  ctx.fill();
  ctx.fillStyle = '#6c4e32';
  roundRect(ctx, -13.4, -6.4, 2.6, 12.8, 1.3);
  ctx.fill();
  ctx.strokeStyle = 'rgba(74,56,37,.5)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(-12.8, -3.5);
  ctx.lineTo(-7.2, -3.5);
  ctx.stroke();

  // cloak
  const cloak = ctx.createRadialGradient(-3, -4, 1, 0, 0, 15);
  cloak.addColorStop(0, '#faf2df');
  cloak.addColorStop(0.62, '#ece1c8');
  cloak.addColorStop(1, '#d2c3a3');
  ctx.fillStyle = cloak;
  ctx.beginPath();
  ctx.ellipse(0, 0, 11.6, 12.8, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(68,87,67,.6)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // cloak fold highlight
  ctx.strokeStyle = 'rgba(255,251,236,.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(-1.5, -1.5, 8.8, -2.5, -1.2);
  ctx.stroke();

  // hood
  ctx.fillStyle = '#41604d';
  ctx.beginPath();
  ctx.arc(2.4, 0, 8.7, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(34,58,45,.55)';
  ctx.lineWidth = 1;
  ctx.stroke();

  // hair
  ctx.fillStyle = '#49382b';
  ctx.beginPath();
  ctx.arc(3, 0, 6.4, 0, TAU);
  ctx.fill();
  // face
  ctx.fillStyle = '#edcda7';
  ctx.beginPath();
  ctx.arc(5.4, 0, 4.1, -1.3, 1.3);
  ctx.closePath();
  ctx.fill();

  // hands
  ctx.fillStyle = '#eac9a3';
  ctx.beginPath();
  ctx.arc(3.2, 10.4, 2.2, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(3.2, -10.4, 2.2, 0, TAU);
  ctx.fill();

  // hood highlight
  ctx.strokeStyle = 'rgba(146,172,133,.6)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.arc(2.4, 0, 8.7, -2.7, -1.5);
  ctx.stroke();

  // scarf knot at the front
  ctx.fillStyle = '#c97a5e';
  ctx.beginPath();
  ctx.ellipse(7.9, 0, 2.9, 3.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(250,214,184,.45)';
  ctx.beginPath();
  ctx.ellipse(7.6, -0.8, 1.1, 1.3, 0, 0, TAU);
  ctx.fill();

  ctx.restore();
}

