input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
page.setDefaultTimeout(20000);
const logs = [];
page.on('console', (m) => { if (m.type() === 'error') logs.push(`[console] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
page.on('response', (r) => { if (r.status() >= 400) logs.push(`HTTP ${r.status()} ${r.url()}`); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__nova?.state.ready);
console.log('init', await page.evaluate(() => window.__nova.info()));
await page.locator('#startBtn').click();
await page.waitForTimeout(1600);
await page.screenshot({ path: join(out, 'day2.jpg'), type: 'jpeg', quality: 82 });
console.log('action css', await page.evaluate(() => { const b = document.getElementById('actionBtn'); const s = getComputedStyle(b); return { transform: s.transform, width: s.width, height: s.height, pe: s.pointerEvents, wrap: document.getElementById('actionWrap').className, innerWidth, innerHeight }; }));

// proper near tree
const near = await page.evaluate(() => window.__nova.near('tree'));
await page.waitForTimeout(600);
console.log('near', near, 'target', await page.evaluate(() => window.__nova.info().target));
const box = await page.locator('#actionBtn').boundingBox();
console.log('action box', box);
if (box) {
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.down();
  await page.waitForTimeout(2800);
  await page.mouse.up();
}
await page.waitForTimeout(400);
console.log('after gather', await page.evaluate(() => ({ inv: window.__nova.info().inventory, target: window.__nova.info().target, stam: window.__nova.info().survival.stamina })));
await page.screenshot({ path: join(out, 'gather2.jpg'), type: 'jpeg', quality: 82 });

// crafting with resources
await page.evaluate(() => { window.__nova.give(20, 20, 5); window.__nova.openCraft(); });
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, 'craft2.jpg'), type: 'jpeg', quality: 82 });
await page.evaluate(() => { window.__nova.closeCraft(); window.__nova.give(20, 20, 5); });
await page.evaluate(() => { window.__nova.state.inventory.wood = 20; window.__nova.state.inventory.stone = 20; window.__nova.openCraft(); });
