602: function spawnHarvestBurst(o, resource) {
603:   const palettes = {
604:     wood: ['#a98055', '#8a6642', '#c7a071', '#7a5b3c'],
605:     stone: ['#a9a696', '#878b7e', '#c5c1ad', '#6f7468'],
606:     food: ['#7da35f', '#5d8a4d', '#c15a4d', '#9bb46f'],
607:   };
608:   const colors = palettes[resource] || palettes.wood;
609:   const shape = resource === 'food' ? 'leaf' : 'spark';
610:   for (let i = 0; i < 8; i++) {
611:     const a = Math.random() * TAU;
612:     const sp = 22 + Math.random() * 55;
613:     state.particles.push({
614:       x: o.x + (Math.random() - 0.5) * 18,
615:       y: o.y + (Math.random() - 0.5) * 12 - 6,
616:       vx: Math.cos(a) * sp,
617:       vy: Math.sin(a) * sp * 0.7 - 10,
618:       life: 0.55 + Math.random() * 0.65,
619:       maxLife: 1.2,
620:       size: 1 + Math.random() * 1.9,
621:       color: colors[(Math.random() * colors.length) | 0],
622:       shape,
623:       rot: Math.random() * TAU,
624:       spin: (Math.random() - 0.5) * 8,
625:       alpha: 0.85,
626:       drag: 2.2,
627:     });
628:   }
629:   if (state.particles.length > 260) state.particles.splice(0, state.particles.length - 260);
630: }
