679: function updateParticles(dt) {
680:   for (let i = state.particles.length - 1; i >= 0; i--) {
681:     const p = state.particles[i];
682:     p.life -= dt;
683:     if (p.life <= 0) { state.particles.splice(i, 1); continue; }
684:     p.x += p.vx * dt;
685:     p.y += p.vy * dt;
686:     if (p.float) p.vy -= 7 * dt;
687:     const drag = Math.exp(-(p.drag ?? 1.2) * dt);
688:     p.vx *= drag;
689:     p.vy *= drag;
690:     if (p.spin) p.rot += p.spin * dt;
691:   }
692:   for (let i = state.floaters.length - 1; i >= 0; i--) {
693:     const f = state.floaters[i];
694:     f.life -= dt;
695:     f.y -= 16 * dt;
696:     if (f.life <= 0) state.floaters.splice(i, 1);
697:   }
698: }
699: 
700: function updateFireflies(dt) {
701:   const darkness = 1 - state.daylight;
702:   if (darkness < 0.2) return;
703:   const p = state.player;
704:   for (const f of state.fireflies) {
705:     f.t += dt;
706:     f.x += Math.cos(f.t * 0.55 + f.phase) * f.speed * dt;
707:     f.y += Math.sin(f.t * 0.42 + f.phase * 1.7) * f.speed * dt;
708:     const dx = f.x - p.x;
709:     const dy = f.y - p.y;
710:     if (dx * dx + dy * dy > 430 * 430) {
711:       const a = Math.random() * TAU;
712:       const r = 110 + Math.random() * 260;
713:       const x = clamp(p.x + Math.cos(a) * r, 30, WORLD - 30);
714:       const y = clamp(p.y + Math.sin(a) * r, 30, WORLD - 30);
715:       if (world.isLand(x, y, 0.02)) {
716:         f.x = x;
717:         f.y = y;
718:       }
719:     }
720:   }
721: }
722: 
723: function updateButterflies(dt, time) {
724:   const p = state.player;
725:   const daylight = state.daylight;
726:   for (const b of state.butterflies) {
727:     if (daylight < 0.25) continue;
728:     b.angle += Math.sin(time * 0.8 + b.phase) * 0.8 * dt;
729:     b.x += Math.cos(b.angle) * b.speed * dt;
730:     b.y += Math.sin(b.angle) * b.speed * dt;
731:     const dx = b.x - p.x;
732:     const dy = b.y - p.y;
733:     if (dx * dx + dy * dy > 520 * 520) {
734:       const a = Math.random() * TAU;
735:       const r = 70 + Math.random() * 300;
736:       const x = clamp(p.x + Math.cos(a) * r, 30, WORLD - 30);
737:       const y = clamp(p.y + Math.sin(a) * r, 30, WORLD - 30);
738:       if (world.isLand(x, y, 0.08)) {
739:         b.x = x;
740:         b.y = y;
741:       }
742:     }
743:   }
744: }
