971: /* ---------------- rendering ---------------- */
972: 
973: function render(time) {
974:   const darkness = 1 - state.daylight;
975:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
976:   ctx.clearRect(0, 0, vw, vh);
977:   ctx.fillStyle = '#16424e';
978:   ctx.fillRect(0, 0, vw, vh);
979: 
980:   const view = {
981:     x1: state.cam.x - vw / (2 * zoom),
982:     x2: state.cam.x + vw / (2 * zoom),
983:     y1: state.cam.y - vh / (2 * zoom),
984:     y2: state.cam.y + vh / (2 * zoom),
985:   };
986: 
987:   ctx.save();
988:   ctx.translate(vw / 2, vh / 2);
989:   ctx.scale(zoom, zoom);
990:   ctx.translate(-state.cam.x, -state.cam.y);
991: 
992:   const sx = clamp(view.x1 - 2, 0, WORLD);
