export function drawPlayer(ctx, p, time, night = 0) {
  const walking = p.moving;
  const bob = walking ? Math.sin(time * 11.5) * 1.4 : Math.sin(time * 2.1) * 0.5;
  const dir = p.dir;
  const step = walking ? Math.sin(time * 11.5) * 3.2 : 0;
  const sway = Math.sin(time * 11.5) * 0.035;

  // shadow
  ctx.fillStyle = 'rgba(16,34,26,.3)';
  ctx.beginPath();
  ctx.ellipse(p.x + 1.5, p.y + 9.5, 13.5, 5.4, 0, 0, TAU);
  ctx.fill();

  if (night > 0.2) { ... same glow ... }

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.rotate(dir);

  // boots
  ctx.fillStyle = '#4a3a2c';
  ctx.beginPath();
  ctx.ellipse(-3.6 + step * 0.35, 10.8, 3.1, 2.4, -0.25, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(-3.6 - step * 0.35, -10.8, 3.1, 2.4, 0.25, 0, TAU);
  ctx.fill();

  // scarf tail
  ctx.fillStyle = '#b96f56';
  ctx.beginPath();
  ctx.moveTo(-4.6, -4.4);
  ctx.quadraticCurveTo(-13.5 - Math.sin(time * 9) * 1.5, -6.2, -14.2, -0.4);
  ctx.quadraticCurveTo(-9.6, -1.8, -5, 1.8);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(232,164,132,.38)';
  ctx.beginPath();
  ctx.ellipse(-9.6, -2.2, 2.7, 0.9, -0.28, 0, TAU);
  ctx.fill();

  // backpack
  ctx.fillStyle = '#7d5c3b';
  roundRect(ctx, -14.6, -5.8, 7.2, 11.6, 3.4);
  ctx.fill();
  ctx.fillStyle = '#67492c';
  roundRect(ctx, -14.6, -5.8, 2.3, 11.6, 1.1);
  ctx.fill();
  ctx.strokeStyle = 'rgba(60,43,28,.45)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(-13.6, -3.4);
  ctx.lineTo(-8.2, -3.4);
  ctx.stroke();

  // cloak / shoulders
  const cloak = ctx.createRadialGradient(1, -3.5, 1, 0, 0, 14);
  cloak.addColorStop(0, '#789366');
  cloak.addColorStop(0.58, '#5f7d54');
  cloak.addColorStop(1, '#46643f');
  ctx.fillStyle = cloak;
  ctx.beginPath();
  ctx.ellipse(0.4, 0, 10.8, 12.1, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(36,57,34,.55)';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // cream shoulder trim (front arc)
  ctx.strokeStyle = 'rgba(238,226,198,.55)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.arc(0.4, 0, 9.4, -1.15, 1.15);
  ctx.stroke();

  // hands
  const handSwing = walking ? step * 0.55 : 0;
  ctx.fillStyle = '#eac9a3';
  ctx.beginPath();
  ctx.arc(2.4 + handSwing, 10.6, 2.15, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(2.4 - handSwing, -10.6, 2.15, 0, TAU);
  ctx.fill();

  // hat brim shadow
  ctx.fillStyle = 'rgba(24,40,26,.28)';
  ctx.beginPath();
  ctx.ellipse(2.9, 1.9, 10.1, 9.3, 0, 0, TAU);
  ctx.fill();

  // straw hat brim
  ctx.save();
  ctx.translate(2.6, 0);
  ctx.rotate(sway);
  const brim = ctx.createRadialGradient(-2.5, -2.5, 1, 0, 0, 10.6);
  brim.addColorStop(0, '#ecd7a6');
  brim.addColorStop(0.62, '#ddc18a');
  brim.addColorStop(1, '#c3a26c');
  ctx.fillStyle = brim;
  ctx.beginPath();
  ctx.ellipse(0, 0, 10.3, 9.4, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(126,96,58,.55)';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // brim rim highlight
  ctx.strokeStyle = 'rgba(255,246,219,.5)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.arc(0, 0, 9.1, -2.55, -0.65);
  ctx.stroke();

  // crown
  const crown = ctx.createRadialGradient(-1.6, -1.8, 0.5, 0, 0, 6.6);
  crown.addColorStop(0, '#e3ca95');
  crown.addColorStop(1, '#bd9c64');
  ctx.fillStyle = crown;
  ctx.beginPath();
  ctx.ellipse(-0.2, 0, 6.2, 5.7, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(126,96,58,.45)';
  ctx.lineWidth = 0.9;
  ctx.stroke();

  // terracotta band
  ctx.strokeStyle = '#b5745b';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.arc(-0.2, 0, 5.3, 0.2, TAU - 0.35);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(247,216,180,.35)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(-0.2, 0, 5.3, 3.5, 5.1);
  ctx.stroke();

  // leaf accent
  ctx.save();
  ctx.translate(5.6, -4.1);
  ctx.rotate(-0.55);
  ctx.fillStyle = '#6f8d52';
  ctx.beginPath();
  ctx.ellipse(0, 0, 3.2, 1.6, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(42,64,36,.5)';
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-2.4, 0);
  ctx.lineTo(2.6, 0);
  ctx.stroke();
  ctx.restore();

  // tiny face peeking under the brim at the front
  ctx.fillStyle = '#e9c9a3';
  ctx.beginPath();
  ctx.arc(10.9, 0, 2.3, -1.15, 1.15);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(180,125,86,.5)';
  ctx.beginPath();
  ctx.arc(11.7, 0, 0.9, -0.8, 0.8);
  ctx.closePath();
  ctx.fill();

  ctx.restore(); // hat sway
  ctx.restore(); // world transform
}
